WITH cleaned AS (SELECT id, account_id, txn_type, amount, merchant, is_flagged, DATE_TRUNC('month', txn_time) AS txn_time_period, COALESCE(merchant, 'NONE') AS resolved_merchant FROM transactions WHERE txn_type = 'CREDIT') SELECT id, account_id, amount, is_flagged, txn_time_period, resolved_merchant, AVG(amount) OVER (PARTITION BY txn_type ORDER BY txn_time_period ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_avg_amount, MIN(amount) OVER (PARTITION BY txn_type ORDER BY txn_time_period ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_amount, SUM(amount) OVER (PARTITION BY txn_type ORDER BY txn_time_period ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_amount, AVG(amount) OVER (ORDER BY amount ASC, id ASC ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS amount_avg_3 FROM cleaned;
